                    #region UPDATE TEMP_CHALLAN_DETAILS

                    //Creation of temp table through SELECT ... INTO ... 
                    strSQL = @"SELECT TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO, 
                                      COUNT(TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO) AS C_NO_OF_DEDUCTEES, 
                                      SUM(TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEPOSITED) AS C_CTRL_TOT_TAX 
                               INTO TEMP_DEDUCTEE_SUMM
                               FROM TEMP_DEDUCTEE_DETAILS
                               GROUP BY TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO";
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        con.Close();
                        con.Dispose();
                        return false;
                    }

                    strSQL = @"UPDATE  TEMP_CHALLAN_DETAILS
                               INNER JOIN 
                               TEMP_DEDUCTEE_SUMM
                               ON TEMP_CHALLAN_DETAILS.RUNNING_SERIAL_NO = TEMP_DEDUCTEE_SUMM.CHALLAN_SERIAL_NO
                               SET TEMP_CHALLAN_DETAILS.CTRL_TOT_TAX     = TEMP_DEDUCTEE_SUMM.C_CTRL_TOT_TAX,
                                   TEMP_CHALLAN_DETAILS.NO_OF_DEDUCTEES  = TEMP_DEDUCTEE_SUMM.C_NO_OF_DEDUCTEES";
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        con.Close();
                        con.Dispose();
                        return false;
                    }

                    strSQL = "DROP TABLE TEMP_DEDUCTEE_SUMM";
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        con.Close();
                        con.Dispose();
                        return false;
                    }

