                            "            'TRF_VCH_CHLN_NO_CELL'," +
                            "            '" + strSheetName + "'," +
                            "            '" + T_Error_Type_Color.MANADATORY_CHECK + "'," +
                            "            '" + cmbFormNo.Text + "'" +
                            "     FROM   TEMP_CHALLAN_DETAILS LEFT JOIN " +
                            "           (SELECT ERR_CELL " +
                            "            FROM   TEMP_ERR_VALIDATION " +
                            "            WHERE  ERR_SHEET = '" + strSheetName + "') AS ERR_V " +
                            "     ON     TEMP_CHALLAN_DETAILS.TRF_VCH_CHLN_NO_CELL     = ERR_V.ERR_CELL " +
                            "     WHERE  ERR_V.ERR_CELL                 IS NULL " +
                            "     AND    VAL(TEMP_CHALLAN_DETAILS.TOTAL_TAX_DEPOSITED) > 0 " +
