                    // VALID DATE CHECK
                    strSQL = "SELECT COUNT(*)" +
                        "     FROM   TEMP_DEDUCTEE_DETAILS" +
                        "     WHERE  ISDATE(DATE_PAYMENT) = 0 " +
                        "     AND    DATE_PAYMENT_CELL NOT IN (SELECT ERR_CELL FROM TEMP_ERR_VALIDATION " +
                        "                                           WHERE ERR_SHEET = '" + strSheetName + "')";
                    //
