                    // TO ALLOW DEDUCTIONS UNDER REMARKS Y TO HAVE DATE FROM THE START OF FINANCIAL YEAR
                    strSQL = "SELECT COUNT(*)" +
                        "     FROM   TEMP_DEDUCTEE_DETAILS" +
                        "     WHERE  (CDATE(" + cmnService.J_SQLDBFormat("DATE_PAYMENT", J_SQLColFormat.DateFormatYYYYMMDD) + ") " +
