                                    "     ON     TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO = TEMP_CHALLAN_DETAILS.RUNNING_SERIAL_NO) " +
                                    "     LEFT JOIN " +
                                    "           (SELECT ERR_CELL " +
                                    "            FROM   TEMP_ERR_VALIDATION " +
                                    "            WHERE  ERR_SHEET = '" + strSheetName + "') AS ERR_V " +
                                    "     ON     TEMP_DEDUCTEE_DETAILS.SECTION_CELL = ERR_V.ERR_CELL) " +
                                    "     LEFT JOIN " +
                                    "           (SELECT REMITTANCE_CODE " +
                                    "            FROM   MST_REMITTANCE) AS REMITT " +
                                    "     ON     TEMP_DEDUCTEE_DETAILS.REMITTANCE = REMITT.REMITTANCE_CODE) " +
                                    "     WHERE  ERR_V.ERR_CELL          IS NULL " +
                                    "     AND    REMITT.REMITTANCE_CODE  IS NULL " +
                                    "     AND    TEMP_DEDUCTEE_DETAILS.REMITTANCE <> '' ";

                                if (dmlService.J_ExecSql(strSQL) == false)
                                    return false;
                            }
                            #endregion

                            #region UNIQUE_ACKN
                            //LENGTH CHECK
                            strSQL = "SELECT COUNT(*)" +
                                "     FROM   TEMP_DEDUCTEE_DETAILS" +
                                "     WHERE  LEN(UNIQUE_ACKN) > 12" +
                                "     AND    UNIQUE_ACKN_CELL NOT IN (SELECT ERR_CELL FROM TEMP_ERR_VALIDATION " +
                                "                                     WHERE  ERR_SHEET = '" + strSheetName + "')";
                            //
                            lngRowCount = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));

                            if (lngRowCount > 0)
                            {
                                //
                                strSQL = " INSERT INTO TEMP_ERR_VALIDATION(ERR_TYPE, ERR_CELL, ERR_COLUMN, ERR_SHEET, ERR_COLOR, ERR_FORM_NO)" +
                                    "      SELECT '" + T_Error_Type.LENGTH_CHECK + "'," +
                                    "             TEMP_DEDUCTEE_DETAILS.UNIQUE_ACKN_CELL AS ERROR_CELL," +
                                    "             'UNIQUE_ACKN_CELL'," +
                                    "             '" + strSheetName + "'," +
                                    "             '" + T_Error_Type_Color.LENGTH_CHECK + "'," +
                                    "             '" + cmbFormNo.Text + "'" +
                                    "     FROM   TEMP_DEDUCTEE_DETAILS LEFT JOIN " +
                                    "           (SELECT ERR_CELL " +
                                    "            FROM   TEMP_ERR_VALIDATION " +
