                                    "     AND    LEN(TEMP_DEDUCTEE_DETAILS.UNIQUE_ACKN) > 12 ";

                                //              
                                if (dmlService.J_ExecSql(strSQL) == false)
                                    return false;
                            }
                            #endregion

                            #region COUNTRY

                            //UPDATE ALL NULL RECORDS TO ''
                            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS SET COUNTRY = '' WHERE COUNTRY IS NULL";
                            dmlService.J_ExecSql(strSQL);

                            //BLANK CHECK
                            strSQL = "SELECT COUNT(*)" +
                                "     FROM   TEMP_DEDUCTEE_DETAILS" +
                                "     WHERE  COUNTRY = ''" +
                                "     AND    COUNTRY_CELL NOT IN (SELECT ERR_CELL FROM TEMP_ERR_VALIDATION " +
                                "                                           WHERE ERR_SHEET = '" + strSheetName + "')";
                            //
                            lngRowCount = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));
                            //
                            if (lngRowCount > 0)
                            {
                                strSQL = " INSERT INTO TEMP_ERR_VALIDATION(ERR_TYPE, ERR_CELL, ERR_COLUMN, ERR_SHEET, ERR_COLOR, ERR_FORM_NO)" +
                                    "      SELECT '" + T_Error_Type.BLANK_NULL_CHECK + "'," +
                                    "             TEMP_DEDUCTEE_DETAILS.COUNTRY_CELL AS ERROR_CELL," +
                                    "             'COUNTRY_CELL'," +
                                    "             '" + strSheetName + "'," +
                                    "             '" + T_Error_Type_Color.BLANK_NULL_CHECK + "'," +
                                    "             '" + cmbFormNo.Text + "'" +
                                    "     FROM   TEMP_DEDUCTEE_DETAILS LEFT JOIN " +
                                    "           (SELECT ERR_CELL " +
                                    "            FROM   TEMP_ERR_VALIDATION " +
                                    "            WHERE  ERR_SHEET = '" + strSheetName + "') AS ERR_V " +
                                    "     ON     TEMP_DEDUCTEE_DETAILS.SECTION_CELL = ERR_V.ERR_CELL " +
                                    "     WHERE  ERR_V.ERR_CELL          IS NULL " +
                                    "     AND    TEMP_DEDUCTEE_DETAILS.COUNTRY      = '' ";

                                //                
                                if (dmlService.J_ExecSql(strSQL) == false)
                                    return false;
                            }
                            //-- VALID
                            strSQL = "SELECT COUNT(*)" +
                                "     FROM   TEMP_DEDUCTEE_DETAILS," +
                                "            TEMP_CHALLAN_DETAILS" +
                                "     WHERE  TEMP_DEDUCTEE_DETAILS.COUNTRY <> '' " +
                                "     AND    TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO = TEMP_CHALLAN_DETAILS.RUNNING_SERIAL_NO " +
                                "     AND    TEMP_DEDUCTEE_DETAILS.COUNTRY NOT IN (SELECT COUNTRY_CODE FROM MST_COUNTRY)" +
                                "     AND    TEMP_DEDUCTEE_DETAILS.COUNTRY_CELL NOT IN (SELECT ERR_CELL FROM TEMP_ERR_VALIDATION " +
