                                    "     SELECT '" + T_Error_Type.VALIDITY_CHECK + "'," +
                                    "            TEMP_DEDUCTEE_DETAILS.COUNTRY_CELL AS ERROR_CELL," +
                                    "            'COUNTRY_CELL'," +
                                    "            '" + strSheetName + "'," +
                                    "            '" + T_Error_Type_Color.VALIDITY_CHECK + "'," +
                                    "            '" + cmbFormNo.Text + "'" +
                                    "     FROM  (((TEMP_DEDUCTEE_DETAILS " +
                                    "     INNER JOIN TEMP_CHALLAN_DETAILS " +
                                    "     ON     TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO = TEMP_CHALLAN_DETAILS.RUNNING_SERIAL_NO) " +
                                    "     LEFT JOIN " +
                                    "           (SELECT ERR_CELL " +
                                    "            FROM   TEMP_ERR_VALIDATION " +
                                    "            WHERE  ERR_SHEET = '" + strSheetName + "') AS ERR_V " +
                                    "     ON     TEMP_DEDUCTEE_DETAILS.SECTION_CELL = ERR_V.ERR_CELL) " +
                                    "     LEFT JOIN " +
                                    "           (SELECT COUNTRY_CODE " +
                                    "            FROM   MST_COUNTRY) AS COUN " +
                                    "     ON     TEMP_DEDUCTEE_DETAILS.COUNTRY = COUN.COUNTRY_CODE) " +
