                                      {"TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEDUCTED = ''" , "F", "0", "F"}};
                //
                string[,] strTaxDep = {{"TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEPOSITED <> ''" , "F", "CCUR(TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEPOSITED)", "F"},
                                      {"TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEPOSITED = ''" , "F", "0", "F"}};
                //
                string[,] strTotValPur = {{"TEMP_DEDUCTEE_DETAILS.GROSSING_UP_TOT_VALUE_PUR <> ''" , "F", "CCUR(TEMP_DEDUCTEE_DETAILS.GROSSING_UP_TOT_VALUE_PUR)", "F"},
                                      {"TEMP_DEDUCTEE_DETAILS.GROSSING_UP_TOT_VALUE_PUR = ''" , "F", "0", "F"}};

                //strSQL = "INSERT INTO TRN_DEDUCTEE_DETAILS " +
                //                 "           (CHALLAN_ID," +
                //                 "            BASIC_INFO_ID," +
                //                 "            SL_NO," +
                //                 "            PARTY_ID," +
                //                 "            PAYMENT_DATE," +
                //                 "            DEDUCTED_DATE," +
                //                 "            PAYMENT_AMOUNT," +
                //                 "            RATE," +
                //                 "            TAX_AMOUNT," +
                //                 "            SURCHARGE_AMOUNT," +
                //                 "            CESS_AMOUNT," +
                //                 "            TOTAL_AMOUNT," +
                //                 "            TAX_DEPOSITED_AMOUNT," +
                //                 "            NON_DEDUCTION_FLAG ";
                //if (cmbFormNo.Text == T_FormNo.F27Q)
                //    strSQL = strSQL + ",GROSSING_UP_INDICATOR)";
                //else if (cmbFormNo.Text == T_FormNo.F27EQ)
                //    strSQL = strSQL + ",TOT_VALUE_PURCHASE)";
                //else
                //    strSQL = strSQL + ")";
                //strSQL = strSQL + " SELECT TRN_CHALLAN.CHALLAN_ID," +
                //       "                   " + BasicInfoID + "," +
                //       //"                   CINT(TEMP_DEDUCTEE_DETAILS.DEDUCTEE_SERIAL_NO)," +
                //       "                   CLNG(TEMP_DEDUCTEE_DETAILS.DEDUCTEE_SERIAL_NO)," +
                //       "                   TEMP_DEDUCTEE_DETAILS.DEDUCTEE_MASTER_ID," +
                //       "                   CDATE(TEMP_DEDUCTEE_DETAILS.DATE_PAYMENT)," +
                //       "                   CDATE(TEMP_DEDUCTEE_DETAILS.DATE_PAYMENT)," +
                //       "                  " + cmnService.J_SQLDBFormat(strAmtPaid, J_SQLColFormat.Case_End) + "," +
                //       "                  " + cmnService.J_SQLDBFormat(strRate, J_SQLColFormat.Case_End) + "," +
                //       "                  " + cmnService.J_SQLDBFormat(strTDS, J_SQLColFormat.Case_End) + "," +
                //       "                  " + cmnService.J_SQLDBFormat(strSurcharge, J_SQLColFormat.Case_End) + "," +
                //       "                  " + cmnService.J_SQLDBFormat(strEducationCess, J_SQLColFormat.Case_End) + "," +
                //       "                  " + cmnService.J_SQLDBFormat(strTaxDed, J_SQLColFormat.Case_End) + "," +
                //       "                  " + cmnService.J_SQLDBFormat(strTaxDep, J_SQLColFormat.Case_End) + "," +
                //       "                   TEMP_DEDUCTEE_DETAILS.REASON";

                //if (cmbFormNo.Text == T_FormNo.F27Q)
                //    strSQL = strSQL + ",TEMP_DEDUCTEE_DETAILS.GROSSING_UP_TOT_VALUE_PUR";
                //else if (cmbFormNo.Text == T_FormNo.F27EQ)
                //    strSQL = strSQL + "," + cmnService.J_SQLDBFormat(strTotValPur, J_SQLColFormat.Case_End) + " ";
                //else
                //    strSQL = strSQL + " ";

                //strSQL = strSQL + " FROM TEMP_DEDUCTEE_DETAILS," +
                //    "                    TRN_CHALLAN" +
                //    //"               WHERE CINT(TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO) = TRN_CHALLAN.SL_NO" +
                //    "               WHERE CLNG(TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO) = TRN_CHALLAN.SL_NO" +
                //    "               AND   TRN_CHALLAN.BASIC_INFO_ID = " + BasicInfoID + " " +
                //    "               ORDER BY TEMP_DEDUCTEE_DETAILS.DEDUCTEE_SERIAL_NO";


                strSQL = "INSERT INTO TRN_DEDUCTEE_DETAILS " +
                                 "           (CHALLAN_ID," +
                                 "            BASIC_INFO_ID," +
                                 "            SL_NO," +
                                 "            PARTY_ID," +
                                 "            PAYMENT_DATE," +
                                 "            DEDUCTED_DATE," +
                                 "            PAYMENT_AMOUNT," +
                                 "            RATE," +
                                 "            TAX_AMOUNT," +
                                 "            SURCHARGE_AMOUNT," +
                                 "            CESS_AMOUNT," +
                                 "            TOTAL_AMOUNT," +
                                 "            TAX_DEPOSITED_AMOUNT," +
                                 "            NON_DEDUCTION_FLAG," +
                                 "            REASON_ID," +
                                 "            SECTION_ID," +
                                 "            CERTIFICATE_NO," +
                                 "            TDS_APPLICABILITY_ID," +
                                 "            REMITTANCE_ID," +
                                 "            UNIQUE_ACKN," +
                                 "            COUNTRY_ID";
                if (cmbFormNo.Text == T_FormNo.F27Q)
                    strSQL = strSQL + ",GROSSING_UP_INDICATOR)";
                else if (cmbFormNo.Text == T_FormNo.F27EQ)
                    strSQL = strSQL + ",TOT_VALUE_PURCHASE)";
                else
                    strSQL = strSQL + ")";
                strSQL = strSQL + " SELECT TRN_CHALLAN.CHALLAN_ID," +
                       "                   " + BasicInfoID + "," +
                    //"                   CINT(TEMP_DEDUCTEE_DETAILS.DEDUCTEE_SERIAL_NO)," +
                       "                   CLNG(TEMP_DEDUCTEE_DETAILS.DEDUCTEE_SERIAL_NO)," +
                       "                   TEMP_DEDUCTEE_DETAILS.DEDUCTEE_MASTER_ID," +
                       "                   CDATE(TEMP_DEDUCTEE_DETAILS.DATE_PAYMENT)," +
                       "                   CDATE(TEMP_DEDUCTEE_DETAILS.DATE_PAYMENT)," +
                       "                  " + cmnService.J_SQLDBFormat(strAmtPaid, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strRate, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strTDS, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strSurcharge, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strEducationCess, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strTaxDed, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strTaxDep, J_SQLColFormat.Case_End) + "," +
                       "                   TEMP_DEDUCTEE_DETAILS.REASON," +
                       "                  " + cmnService.J_SQLDBFormat("REASON_ASPER_FORM.REASON_ID", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + "," +
                       "                  " + cmnService.J_SQLDBFormat("MST_SECTION.SECTION_ID", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + "," +
                       "                   TEMP_DEDUCTEE_DETAILS.CERTIFICATE_NO," +
                       "                  " + cmnService.J_SQLDBFormat("MST_TDS_APPLICABILITY.TDS_APPLICABILITY_ID", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + "," +
                       "                  " + cmnService.J_SQLDBFormat("MST_REMITTANCE.REMITTANCE_ID", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + "," +
                       "                   TEMP_DEDUCTEE_DETAILS.UNIQUE_ACKN," +
                       "                  " + cmnService.J_SQLDBFormat("MST_COUNTRY.COUNTRY_ID", J_ColumnType.Integer, J_SQLColFormat.NullCheck);

                if (cmbFormNo.Text == T_FormNo.F27Q)
                    strSQL = strSQL + ",TEMP_DEDUCTEE_DETAILS.GROSSING_UP_TOT_VALUE_PUR";
                else if (cmbFormNo.Text == T_FormNo.F27EQ)
                    strSQL = strSQL + "," + cmnService.J_SQLDBFormat(strTotValPur, J_SQLColFormat.Case_End) + " ";
                else
                    strSQL = strSQL + " ";

                strSQL = strSQL + " FROM ((((((TEMP_DEDUCTEE_DETAILS " +
                    "               INNER JOIN TRN_CHALLAN " +
                    "                       ON CLNG(TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO) = TRN_CHALLAN.SL_NO)" +
                    "               LEFT  JOIN (SELECT REASON_ID, " +
                    "                              REASON " +
                    "                       FROM MST_REASON " +
                    "                       WHERE FORM_NO = '" + cmbFormNo.Text + "') AS REASON_ASPER_FORM " +
                    "                       ON TEMP_DEDUCTEE_DETAILS.REASON = REASON_ASPER_FORM.REASON) " +
                    "               LEFT  JOIN MST_SECTION " +
                    "                       ON TEMP_DEDUCTEE_DETAILS.SECTION = MST_SECTION.SECTION_NO) " +
                    "               LEFT  JOIN MST_COUNTRY " +
                    "                       ON TEMP_DEDUCTEE_DETAILS.COUNTRY = MST_COUNTRY.COUNTRY_CODE) " +
                    "               LEFT  JOIN MST_TDS_APPLICABILITY " +
                    "                       ON TEMP_DEDUCTEE_DETAILS.TDS_APPLICABILITY = MST_TDS_APPLICABILITY.TDS_APPLICABILITY_CODE) " +
                    "               LEFT  JOIN MST_REMITTANCE " +
                    "                       ON TEMP_DEDUCTEE_DETAILS.REMITTANCE = MST_REMITTANCE.REMITTANCE_CODE) " +
                    "               WHERE TRN_CHALLAN.BASIC_INFO_ID = " + BasicInfoID + " " +
                    "               ORDER BY TEMP_DEDUCTEE_DETAILS.DEDUCTEE_SERIAL_NO";


                //-----------------------------------------------------------
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return false;
                }

                if (Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex) < T_FinancialYearID.F2013_14ID)
                {
                    strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                             "INNER JOIN TRN_CHALLAN " +
                             "ON     TRN_DEDUCTEE_DETAILS.CHALLAN_ID = TRN_CHALLAN.CHALLAN_ID " +
                             "SET    TRN_DEDUCTEE_DETAILS.SECTION_ID = TRN_CHALLAN.SECTION_ID " +
                             "WHERE  TRN_CHALLAN.BASIC_INFO_ID = " + BasicInfoID;
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        return false;
                    }
            }

                //UPDATE DEDUCTED DATE TO BLANK IF TOTAL DEDUCTION IS ZERO
                strSQL = "UPDATE TRN_DEDUCTEE_DETAILS SET DEDUCTED_DATE = NULL WHERE TOTAL_AMOUNT = 0";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return false;
                }


                // INSERTING CONTROL TOTALS OF CHALLAN IN TEMP_TABLE

                strSQL = " INSERT INTO TEMP_CHALLAN_CONTROL_TOTALS " +
                    "                  (CHALLAN_ID, " +
                    "                  SUM_TAX_AMOUNT,  " +
                    "                  SUM_SURCHARGE_AMOUNT, " +
                    "                  SUM_CESS_AMOUNT,  " +
                    "                  SUM_TOTAL_AMOUNT,  " +
                    "                  SUM_TAX_DEPOSITED_AMOUNT)  " +
                    "      SELECT CHALLAN_ID,  " +
                    "             SUM(TAX_AMOUNT), " +
                    "             SUM(SURCHARGE_AMOUNT),  " +
                    "             SUM(CESS_AMOUNT),  " +
                    "             SUM(TOTAL_AMOUNT),  " +
                    "             SUM(TAX_DEPOSITED_AMOUNT)  " +
                    "      FROM   TRN_DEDUCTEE_DETAILS  " +
                    "      WHERE  BASIC_INFO_ID = " + BasicInfoID + "" +
                    "      GROUP  BY CHALLAN_ID";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return false;
                }
                //UPDATE CONTROL TOTALS OF CHALLAN TABLE USING TEMP TABLE
                strSQL = "UPDATE TRN_CHALLAN" +
                "                INNER JOIN  TEMP_CHALLAN_CONTROL_TOTALS " +
                "                  ON TRN_CHALLAN.CHALLAN_ID = TEMP_CHALLAN_CONTROL_TOTALS.CHALLAN_ID " +
                "         SET    TRN_CHALLAN.CTRL_TDS       = TEMP_CHALLAN_CONTROL_TOTALS.SUM_TAX_AMOUNT," +
                "                TRN_CHALLAN.CTRL_SURCHARGE = TEMP_CHALLAN_CONTROL_TOTALS.SUM_SURCHARGE_AMOUNT," +
                "                TRN_CHALLAN.CTRL_EDU_CESS  = TEMP_CHALLAN_CONTROL_TOTALS.SUM_CESS_AMOUNT," +
                "                TRN_CHALLAN.CTRL_TOT       = TEMP_CHALLAN_CONTROL_TOTALS.SUM_TOTAL_AMOUNT," +
                "                TRN_CHALLAN.CTRL_TOT_TAX   = TEMP_CHALLAN_CONTROL_TOTALS.SUM_TAX_DEPOSITED_AMOUNT" +
                "         WHERE TRN_CHALLAN.BASIC_INFO_ID = " + BasicInfoID + " ";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return false;
                }
                //
                return true;
            }
            catch (Exception e)
            {
                return false;
            }
        }

