        #region INSERT_MASTER_DATA
        public bool INSERT_MASTER_DATA()
        {
            try
            {
                if (cmbFormNo.Text == T_FormNo.F24QSalaryDetails)
                {
                    //INSERTING NEW EMPLOYEES FOUND IN EXCEL TO THE MASTER
                    strSQL = "INSERT INTO MST_EMPLOYEE " +
                       "                 (EMPLOYEE_NAME," +
                       "                  EMPLOYEE_PAN," +
                       "                  COMPANY_ID," +
                       "                  GROUP_ID) " +
                       "      SELECT      DEDUCTEE_NAME," +
                       "                  DEDUCTEE_PAN," +
                       "                  COMPANY_ID," +
                       "                  '" + TDSMAN.Classes.TDSMAN.T_pGroupId + "'" +
                       "      FROM        TEMP_DEDUCTEE_MASTER";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                    //ADD EMPLOYEE_MASTER_ID IN TEMP_DEDUCTEE_DETAILS FOR LINKING WITH EMPLOYEE MASTER

                    //FOR VALID PAN -- LINKING PAN WITH MASTER
                    strSQL = "UPDATE TEMP_SALARY_DETAILS " +
                      "         INNER JOIN MST_EMPLOYEE " +
                      "                 ON TEMP_SALARY_DETAILS.EMPLOYEE_PAN = MST_EMPLOYEE.EMPLOYEE_PAN  " +
                      "       SET    TEMP_SALARY_DETAILS.EMPLOYEE_ID     = MST_EMPLOYEE.EMPLOYEE_ID " +
                      "       WHERE  TEMP_SALARY_DETAILS.EMPLOYEE_PAN    <> 'PANNOTAVBL'" +
                      "       AND    MST_EMPLOYEE.COMPANY_ID             = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + " ";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                    // FOR PANNOTAVBL -- LINKING NAME WITH MASTER
                    strSQL = "UPDATE TEMP_SALARY_DETAILS " +
                      "         INNER JOIN MST_EMPLOYEE " +
                      "         ON TEMP_SALARY_DETAILS.EMPLOYEE_NAME = MST_EMPLOYEE.EMPLOYEE_NAME  " +
                      "  SET    TEMP_SALARY_DETAILS.EMPLOYEE_ID      = MST_EMPLOYEE.EMPLOYEE_ID " +
                      "  WHERE  TEMP_SALARY_DETAILS.EMPLOYEE_PAN     = 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.EMPLOYEE_PAN            = 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.COMPANY_ID              = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + " ";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                    // UPDATE CATEGORY
                    // FOR  PANNOTAVBL
                    strSQL = "UPDATE MST_EMPLOYEE " +
                      "         INNER JOIN TEMP_SALARY_DETAILS " +
                      "         ON TEMP_SALARY_DETAILS.EMPLOYEE_NAME = MST_EMPLOYEE.EMPLOYEE_NAME  " +
                      "  SET    MST_EMPLOYEE.CATEGORY                = TEMP_SALARY_DETAILS.CATEGORY " +
                      "  WHERE  TEMP_SALARY_DETAILS.EMPLOYEE_PAN     = 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.EMPLOYEE_PAN            = 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.COMPANY_ID              = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + " ";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                    // FOR  PANAVBL
                    strSQL = "UPDATE MST_EMPLOYEE " +
                      "         INNER JOIN TEMP_SALARY_DETAILS " +
                      "         ON TEMP_SALARY_DETAILS.EMPLOYEE_PAN  = MST_EMPLOYEE.EMPLOYEE_PAN  " +
                      "  SET    MST_EMPLOYEE.CATEGORY                = TEMP_SALARY_DETAILS.CATEGORY " +
                      "  WHERE  TEMP_SALARY_DETAILS.EMPLOYEE_PAN     <> 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.EMPLOYEE_PAN            <> 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.COMPANY_ID              = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + " ";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                }
                else if (cmbFormNo.Text == T_FormNo.F24Q)
                {
                    //INSERTING NEW EMPLOYEES FOUND IN EXCEL TO THE MASTER
                    strSQL = "INSERT INTO MST_EMPLOYEE " +
                       "                 (EMPLOYEE_NAME," +
                       "                  EMPLOYEE_PAN," +
                       "                  COMPANY_ID," +
                       "                  GROUP_ID) " +
                       "      SELECT      DEDUCTEE_NAME," +
                       "                  DEDUCTEE_PAN," +
                       "                  COMPANY_ID," +
                       "                  '" + TDSMAN.Classes.TDSMAN.T_pGroupId + "'" +
                       "      FROM        TEMP_DEDUCTEE_MASTER";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                    //ADD EMPLOYEE_MASTER_ID IN TEMP_DEDUCTEE_DETAILS FOR LINKING WITH EMPLOYEE MASTER

                    //FOR VALID PAN -- LINKING PAN WITH MASTER
                    strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                      "         INNER JOIN MST_EMPLOYEE " +
                      "         ON TEMP_DEDUCTEE_DETAILS.DEDUCTEE_PAN    = MST_EMPLOYEE.EMPLOYEE_PAN  " +
                      "  SET    TEMP_DEDUCTEE_DETAILS.DEDUCTEE_MASTER_ID = MST_EMPLOYEE.EMPLOYEE_ID " +
                      "  WHERE  TEMP_DEDUCTEE_DETAILS.DEDUCTEE_PAN       <> 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.COMPANY_ID                  = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + " ";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                    // FOR PANNOTAVBL -- LINKING NAME WITH MASTER
                    strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                      "         INNER JOIN MST_EMPLOYEE " +
                      "         ON TEMP_DEDUCTEE_DETAILS.DEDUCTEE_NAME   = MST_EMPLOYEE.EMPLOYEE_NAME  " +
                      "  SET    TEMP_DEDUCTEE_DETAILS.DEDUCTEE_MASTER_ID = MST_EMPLOYEE.EMPLOYEE_ID " +
                      "  WHERE  TEMP_DEDUCTEE_DETAILS.DEDUCTEE_PAN       = 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.EMPLOYEE_PAN                = 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.COMPANY_ID                  = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + " ";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;
                }
                else
                {

                    strSQL = "UPDATE TEMP_DEDUCTEE_MASTER " +
                             "SET DEDUCTEE_CODE = FORMAT(DEDUCTEE_CODE, \"0#\")";

                    dmlService.J_ExecSql(strSQL, J_SQLType.DML);


                    //INSERT TEMPORARY MASTER CREATED FOR EXCEL IN MAIN MASTER
                    strSQL = "INSERT INTO MST_DEDUCTEE " +
                       "                 (DEDUCTEE_NAME," +
                       "                  DEDUCTEE_PAN," +
                       "                  DEDUCTEE_CODE," +
                       "                  GROUP_ID) " +
                       "      SELECT      DEDUCTEE_NAME," +
                       "                  DEDUCTEE_PAN," +
                       "                  DEDUCTEE_CODE," +
                       "                  '" + TDSMAN.Classes.TDSMAN.T_pGroupId + "'" +
                       "      FROM        TEMP_DEDUCTEE_MASTER";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                    //ADD DEDUCTEE_MASTER_ID IN TEMP_DEDUCTEE_DETAILS FOR LINKING WITH DEDUCTEE MASTER
                    strSQL = @"UPDATE TEMP_DEDUCTEE_DETAILS 
                               INNER JOIN MST_DEDUCTEE 
                                 ON TEMP_DEDUCTEE_DETAILS.DEDUCTEE_PAN  = MST_DEDUCTEE.DEDUCTEE_PAN 
                        SET    TEMP_DEDUCTEE_DETAILS.DEDUCTEE_MASTER_ID = MST_DEDUCTEE.DEDUCTEE_ID 
                        WHERE  TEMP_DEDUCTEE_DETAILS.DEDUCTEE_PAN       <> 'PANNOTAVBL'";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

//                    strSQL = @"UPDATE TEMP_DEDUCTEE_DETAILS 
//                               INNER JOIN MST_DEDUCTEE 
//                                 ON TEMP_DEDUCTEE_DETAILS.DEDUCTEE_NAME = MST_DEDUCTEE.DEDUCTEE_NAME 
//                        SET    TEMP_DEDUCTEE_DETAILS.DEDUCTEE_MASTER_ID = MST_DEDUCTEE.DEDUCTEE_ID 
//                        WHERE  TEMP_DEDUCTEE_DETAILS.DEDUCTEE_PAN       = 'PANNOTAVBL'";

                    //-- MODIFIED BY ANIK.G @ 2013/05/06
                    strSQL = @"UPDATE TEMP_DEDUCTEE_DETAILS 
                               INNER JOIN MST_DEDUCTEE 
                                 ON TEMP_DEDUCTEE_DETAILS.DEDUCTEE_NAME = MST_DEDUCTEE.DEDUCTEE_NAME 
                        SET    TEMP_DEDUCTEE_DETAILS.DEDUCTEE_MASTER_ID = MST_DEDUCTEE.DEDUCTEE_ID 
                        WHERE  TEMP_DEDUCTEE_DETAILS.DEDUCTEE_PAN       = 'PANNOTAVBL'
                        AND    MST_DEDUCTEE.DEDUCTEE_PAN                = 'PANNOTAVBL'";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;
                }
                
                //
                strSQL = "SELECT COUNT(*) FROM TEMP_DEDUCTEE_DETAILS WHERE DEDUCTEE_MASTER_ID = 0";
                if (Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL)) == 0)
                    return true;
                else
                    return false;
            }
            catch (Exception e)
            {
                return false;
            }
        }
        #endregion

